import subprocess
import difflib
import sys

def run(args):
    return subprocess.run(args, capture_output=True)

def blob(stage, path):
    proc = run(['git', 'show', ':' + str(stage) + ':' + path])
    if proc.returncode != 0:
        return None
    return proc.stdout.decode('utf-8', 'surrogateescape')

raw = run(['git', 'diff', '--name-only', '--diff-filter=U', '-z']).stdout
paths = [item for item in raw.decode('utf-8', 'surrogateescape').split('\0') if item]

def annotate(base, side):
    n = len(base)
    ins = [[] for _ in range(n + 1)]
    rep = [('same', None)] * n
    matcher = difflib.SequenceMatcher(None, base, side, autojunk=False)
    for tag, i1, i2, j1, j2 in matcher.get_opcodes():
        if tag == 'equal':
            k = 0
            while k < i2 - i1:
                rep[i1 + k] = ('same', [side[j1 + k]])
                k += 1
        elif tag == 'insert':
            ins[i1].extend(side[j1:j2])
        elif tag == 'delete':
            k = i1
            while k < i2:
                rep[k] = ('del', [])
                k += 1
        else:
            if i2 - i1 == j2 - j1:
                k = 0
                while k < i2 - i1:
                    rep[i1 + k] = ('mod', [side[j1 + k]])
                    k += 1
            else:
                k = i1
                while k < i2:
                    rep[k] = ('del', [])
                    k += 1
                ins[i1].extend(side[j1:j2])
    return ins, rep

def merge3(base, ours, theirs):
    o_ins, o_rep = annotate(base, ours)
    t_ins, t_rep = annotate(base, theirs)
    res = []
    n = len(base)
    p = 0
    while p <= n:
        res.extend(o_ins[p])
        res.extend(t_ins[p])
        if p < n:
            o = o_rep[p]
            t = t_rep[p]
            if o[0] == 'del' or t[0] == 'del':
                pass
            elif o[0] == 'mod' and t[0] == 'mod':
                if o[1] == t[1]:
                    res.extend(o[1])
                else:
                    res.extend(t[1])
            elif o[0] == 'mod':
                res.extend(o[1])
            elif t[0] == 'mod':
                res.extend(t[1])
            elif o[1] is not None:
                res.extend(o[1])
            else:
                res.extend(t[1])
        p += 1
    return res

for path in paths:
    base = blob(1, path)
    ours = blob(2, path)
    theirs = blob(3, path)
    if ours is None:
        run(['git', 'rm', '-f', '--', path])
        continue
    if base is None or theirs is None:
        data = ours
    else:
        merged = merge3(base.splitlines(keepends=True),
                        ours.splitlines(keepends=True),
                        theirs.splitlines(keepends=True))
        data = ''.join(merged)
    handle = open(path, 'wb')
    handle.write(data.encode('utf-8', 'surrogateescape'))
    handle.close()
    run(['git', 'add', '--', path])
sys.exit(0)
